-- fix_collaborator_triggers_tenant_id.sql
--
-- The trg_project_creator_collab (and any equivalent triggers on organizations
-- and objectives) auto-insert a row into public.collaborators when a new object
-- is created.  The original trigger bodies omit tenant_id, which is NOT NULL,
-- causing every project/org/objective insert to fail.
--
-- This migration patches each trigger function to forward NEW.tenant_id.
-- Safe to run multiple times (CREATE OR REPLACE).

-- Projects
CREATE OR REPLACE FUNCTION public.trg_project_creator_collab()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO public.collaborators
    (object_type, object_id, user_id, role, access_source, status, tenant_id)
  VALUES
    ('init', NEW.id, NEW.owner_central_id, 'creator', 'direct', 'active', NEW.tenant_id)
  ON CONFLICT (object_type, object_id, user_id) DO NOTHING;
  RETURN NEW;
END;
$$;

-- Organizations (same pattern — patch if the trigger exists)
CREATE OR REPLACE FUNCTION public.trg_organization_creator_collab()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO public.collaborators
    (object_type, object_id, user_id, role, access_source, status, tenant_id)
  VALUES
    ('init', NEW.id, NEW.owner_central_id, 'creator', 'direct', 'active', NEW.tenant_id)
  ON CONFLICT (object_type, object_id, user_id) DO NOTHING;
  RETURN NEW;
END;
$$;

-- Objectives (same pattern — patch if the trigger exists)
CREATE OR REPLACE FUNCTION public.trg_objective_creator_collab()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO public.collaborators
    (object_type, object_id, user_id, role, access_source, status, tenant_id)
  VALUES
    ('init', NEW.id, NEW.owner_central_id, 'creator', 'direct', 'active', NEW.tenant_id)
  ON CONFLICT (object_type, object_id, user_id) DO NOTHING;
  RETURN NEW;
END;
$$;
